mapper.sql:
FROM student_score ss LEFT JOIN course c ON ss.course_id = c.id LEFT JOIN sys_user stu ON ss.student_id = stu.id WHERE ss.status = 1 AND c.status = 1 AND stu.role = 'student' AND ss.score IS NOT NULL
AND c.semester = #{dto.semester}
AND stu.college_id = #{dto.collegeId}

mapper.select:
SELECT org_college.name AS colleges, AVG(ss.score) AS avgScores, COUNT(DISTINCT ss.student_id) AS studentCounts FROM student_score ss LEFT JOIN course c ON ss.course_id = c.id LEFT JOIN sys_user stu ON ss.student_id = stu.id LEFT JOIN org_college ON stu.college_id = org_college.id WHERE ss.status = 1 AND c.status = 1 AND stu.role = 'student' AND ss.score IS NOT NULL
AND c.semester = #{dto.semester}
AND stu.college_id = #{dto.collegeId}
GROUP BY org_college.name

SELECT stu.username AS studentNo, stu.real_name AS studentName, c.name AS courseName, ss.score AS totalScore, '成绩低于60分，判定为异常成绩' AS reason, org_college.name AS collegeName, c.semester AS semester FROM student_score ss LEFT JOIN course c ON ss.course_id = c.id LEFT JOIN sys_user stu ON ss.student_id = stu.id LEFT JOIN org_college ON stu.college_id = org_college.id WHERE ss.status = 1 AND c.status = 1 AND stu.role = 'student' AND ss.score IS NOT NULL AND ss.score < 60
AND stu.college_id = #{dto.collegeId}
AND c.semester = #{dto.semester}
ORDER BY org_college.name, stu.username

SELECT c.name AS courseName, c.credit AS credit, sc.usual_score AS usualScore, sc.final_score AS finalScore, sc.score AS totalScore, c.semester AS semester FROM student_score sc INNER JOIN course c ON sc.course_id = c.id WHERE sc.student_id = #{studentId}
AND c.semester = #{dto.semester}
ORDER BY c.semester DESC, c.name
